import { createMiddleware } from '@frontman-ai/nextjs';
import { NextRequest, NextResponse } from 'next/server';

const frontman = createMiddleware({
  host: 'test.frontman.dev',
});

export async function proxy(req: NextRequest): Promise<NextResponse> {
  const response = await frontman(req);
  if (response) return response;

  // Custom proxy for API routes
  if (req.nextUrl.pathname.startsWith('/api/external')) {
    return NextResponse.rewrite(new URL('https://external-api.com' + req.nextUrl.pathname));
  }
  return NextResponse.next();
}

export const config = {
  matcher: ['/frontman', '/frontman/:path*', '/:path*/frontman', '/:path*/frontman/', '/api/external/:path*'],
  runtime: 'nodejs',
};
